package org.telegram.messenger.tetogram;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.telegram.messenger.tetogram.AppearanceEditorPolicy.*;
public class AppearanceEditorPolicyTest {
 @Test public void wallpaperFieldsHaveOneCategoryRegardlessOfScopeDomain(){for(String key:new String[]{"wallpaper.file","list.wallpaper.speed","banner.wallpaper.blur","light.chat_wallpaper","dark.list.chat_wallpaper_gradient_to1"})assertEquals(Category.WALLPAPERS,category(key));}
 @Test public void listAndMessagesAreSeparate(){assertEquals(Category.LIST,category("light.list.chats_name"));assertEquals(Category.CHATS,category("light.chat_outBubble"));assertEquals(Category.SECTIONS,category("dark.list.chats_tabText"));}
 @Test public void resettingOneCategoryPreservesOtherValuesAndOriginal(){AppearanceConfig.Style s=new AppearanceConfig.Style();s.set("wallpaper.zoom","2");s.set("bubble.inRadius","20");s.color(false,"list.chats_name",4);AppearanceConfig.Style reset=resetCategory(s,Category.WALLPAPERS);assertFalse(reset.values.containsKey("wallpaper.zoom"));assertEquals("20",reset.values.get("bubble.inRadius"));assertEquals(3,s.values.size());}
 @Test public void viewChangesDoNotDirtyDraftAndChangesCanBeUndone(){AppearanceConfig.Style original=new AppearanceConfig.Style(),draft=original.copy();assertFalse(dirty(original,draft));define("wallpaper.speed");preview(Category.PROFILE);assertFalse(dirty(original,draft));draft.set("wallpaper.speed","1.5");assertTrue(dirty(original,draft));draft.values.remove("wallpaper.speed");assertFalse(dirty(original,draft));}
 @Test public void ordinaryColorChangesKeepVideoIdentity(){AppearanceConfig.Resolved before=new AppearanceConfig.Resolved(),after=new AppearanceConfig.Resolved();before.values.put("wallpaper.file","video");before.values.put("wallpaper.type","video");after.values.putAll(before.values);after.values.put("light.chat_outBubble","123");assertTrue(sameMedia(before,after));after.values.put("wallpaper.file","replacement");assertFalse(sameMedia(before,after));}
 @Test public void localEditsStillRespectInheritanceAndAccountCopies(){AppearanceConfig config=new AppearanceConfig();config.edit("global").set("bubble.inRadius","12");config.edit("chat:42").set("bubble.inRadius","24");AppearanceConfig copy=config.copy();assertEquals("24",copy.resolve(AppearanceConfig.Context.direct(42,0)).get("bubble.inRadius"));assertEquals("12",copy.resolve(AppearanceConfig.Context.direct(43,0)).get("bubble.inRadius"));copy.scopes.remove("chat:42");assertEquals("24",config.resolve(AppearanceConfig.Context.direct(42,0)).get("bubble.inRadius"));}
 @Test public void unsupportedScopeControlsAreNotOffered(){assertFalse(supports("profile:42",Category.CHATS));assertFalse(supports("chat:42",Category.PROFILE));assertFalse(supports("chat:42",Category.ADVANCED));assertTrue(supports("profile:42",Category.WALLPAPERS));assertTrue(supports("folder:tg:2",Category.SECTIONS));}
 @Test public void definitionsKeepNumericAndBooleanParallaxDistinct(){assertEquals(Kind.NUMBER,define("banner.parallax").kind);assertEquals(Kind.BOOLEAN,define("wallpaper.parallax").kind);assertEquals("false",define("wallpaper.parallax").defaultValue);assertEquals(Kind.TEXT,define("launcher.emoji").kind);assertEquals("0.78",define("launcher.iconScale").defaultValue);assertEquals("280",define("banner.height").defaultValue);assertEquals("1",define("list.rowOpacity").defaultValue);}
 @Test public void resettingOneBackgroundDoesNotRemoveOtherSurfaces(){AppearanceConfig.Style s=new AppearanceConfig.Style();s.set("wallpaper.file","chat");s.set("list.wallpaper.file","list");s.set("banner.wallpaper.file","profile");AppearanceConfig.Style copy=resetWallpaper(s,"list.wallpaper");assertEquals("chat",copy.values.get("wallpaper.file"));assertEquals("profile",copy.values.get("banner.wallpaper.file"));assertFalse(copy.values.containsKey("list.wallpaper.file"));}
}
